import json
rm=json.load(open('/tmp/j68_rm2.json'))['items']
tk=json.load(open('/tmp/j68_tk.json'))
ts=tk['tasks'] if isinstance(tk,dict) else tk
live={t['id'] for t in ts if t.get('status')=='running'}
byid={i['id']:i for i in rm}
act=[i for i in rm if i['status']=='active']
def desc(nid):
    return [i for i in rm if i.get('parent')==nid]
def has_live_desc(nid):
    for i in rm:
        p=i.get('parent'); 
    # walk down
    stack=desc(nid); 
    while stack:
        n=stack.pop()
        if n.get('owner') in live: return n['id']
        stack+=desc(n['id'])
    return None
print('live tasks:',sorted(live))
print()
for i in act:
    o=i.get('owner') or ''
    if o in live: verdict='DIRECT (owner %s live)'%o
    else:
        d=has_live_desc(i['id'])
        verdict='ANCESTOR of live %s'%d if d else ('STALE-ACTIVE (owner %r)'%o)
    print('%-45s %s'%(i['id'],verdict))
EOF

